//! XML exactly as soapbox-race-core's JAXB writes it, and as leniently as JAXB
//! reads it.
//!
//! [`dto`] holds upstream's ~170 XML classes, generated by `tools/gen.py dtos`
//! from JAXB's own runtime model of them (`fixtures/dto/schema.json`). Writing
//! is pinned byte for byte by goldens marshalled by upstream's `JAXBUtility`;
//! reading follows the recorded behaviour of `JAXBUtility.unMarshal`
//! (`fixtures/dto/unmarshal.json`).

pub mod dto;
mod read;
mod value;
mod writer;

pub use read::{Element, XmlError, parse};
pub use value::{DateTime, XmlValue};
pub use writer::{XmlWriter, escape_text};

/// A class JAXB marshals: its attributes and child elements, in JAXB's order
/// (base-class properties first).
pub trait XmlType: Default {
    fn write_attributes(&self, _w: &mut XmlWriter) {}
    fn write_children(&self, w: &mut XmlWriter);
    /// Fill in from an element, as JAXB fills a fresh instance: unknown
    /// elements are skipped, a repeated element replaces the earlier one,
    /// unparsable values leave the property as it was.
    fn read_from(&mut self, e: &Element);

    fn read(e: &Element) -> Self {
        let mut value = Self::default();
        value.read_from(e);
        value
    }
}

/// A class `JAXBUtility.marshal` can write as a document: the root element is
/// its `@XmlRootElement` name, else its `@XmlType` name.
pub trait XmlRoot: XmlType {
    const ROOT: &'static str;
}

/// A complete XML document.
pub trait ToXml {
    fn to_xml(&self) -> String;
}

impl<T: XmlRoot> ToXml for T {
    fn to_xml(&self) -> String {
        let mut w = XmlWriter::new();
        w.bean(T::ROOT, self);
        w.finish()
    }
}

/// `JAXBUtility.unMarshal(xml, T.class)`: the root element's name is ignored,
/// as upstream unmarshals by declared type.
pub fn from_xml<T: XmlType>(xml: &str) -> Result<T, XmlError> {
    Ok(T::read(&parse(xml)?))
}
